// Measures decompiler recovery from stripped libraries generated by this project.
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeSet;
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.mem.MemoryBlock;
import ghidra.program.model.pcode.PcodeOp;

public class MeasureHelperRecovery extends GhidraScript {
    private static final int SECONDS_PER_FUNCTION = 15;

    @Override
    protected void run() throws Exception {
        var entries = new LinkedHashMap<Address, String>();
        for (MemoryBlock section : currentProgram.getMemory().getBlocks()) {
            String name = section.getName();
            if (section.isExecute() && (name.startsWith(".nar") || name.startsWith(".nah")))
                entries.put(section.getStart(), name);
        }
        println("HELPER_INPUT\t" + currentProgram.getName() + "\t" + currentProgram.getExecutableSHA256()
            + "\t" + entries.size());
        if (entries.isEmpty()) return;
        report("auto", entries);
        for (var entry : entries.entrySet()) {
            monitor.checkCancelled();
            if (getFunctionAt(entry.getKey()) == null) {
                disassemble(entry.getKey());
                createFunction(entry.getKey(), null);
            }
        }
        report("section-entry", entries);
    }

    private void report(String phase, Map<Address, String> entries) throws Exception {
        var decompiler = new DecompInterface();
        try {
            decompiler.toggleCCode(false);
            if (!decompiler.openProgram(currentProgram))
                throw new IllegalStateException(decompiler.getLastMessage());
            for (var entry : entries.entrySet()) {
                monitor.checkCancelled();
                Function function = getFunctionAt(entry.getKey());
                var calls = new TreeSet<String>();
                boolean decompiled = false;
                if (function != null) {
                    var result = decompiler.decompileFunction(function, SECONDS_PER_FUNCTION, monitor);
                    if (result != null && result.decompileCompleted() && result.getHighFunction() != null) {
                        decompiled = true;
                        var operations = result.getHighFunction().getPcodeOps();
                        while (operations.hasNext()) {
                            var op = operations.next();
                            if (op.getOpcode() == PcodeOp.CALL) {
                                String destination = entries.get(op.getInput(0).getAddress());
                                if (destination != null && destination.startsWith(".nah")) calls.add(destination);
                            }
                        }
                    }
                }
                println("HELPER_RESULT\t" + phase + "\t" + entry.getValue() + "\t" + entry.getKey()
                    + "\t" + (function != null) + "\t" + decompiled + "\t" + String.join(",", calls));
            }
        } finally {
            decompiler.dispose();
        }
    }
}
